/* Track-while-scan: a true-black scan volume, white contacts, one blue for the sweep and the PM's marks,
   amber only for weakened / lost tracks. Numerals carry the information; words are labels, never paragraphs. */
:root {
  color-scheme: dark;

  /* ground */
  --void: #000000;
  --glass: rgba(10, 12, 15, 0.72);
  --hair: rgba(255, 255, 255, 0.09);
  --hair-2: rgba(255, 255, 255, 0.16);
  /* the frameless panel field (inspector, hover card, filter values, audit trail, dock): plain black at 86%, as the
     audit trail had it; no tint, no glow */
  --field: rgba(0, 0, 0, 0.86);

  /* ink */
  --ink: #f2f4f7;
  --ink-2: #b4bac4;
  --ink-3: #868d99;   /* ≥ 4.5:1 on black */

  /* signal */
  --sweep: #1c69d4;
  --sweep-hi: #4d94ff;
  --sweep-wash: rgba(28, 105, 212, 0.18);
  --lost: #f5a524;

  /* type */
  --font: "Mona Sans Variable", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --t-micro: 11px;
  --t-label: 12px;
  --t-body: 14px;
  --t-read: 18px;

  /* space, shape, motion */
  --edge: 24px;
  --r: 10px;
  --ease: cubic-bezier(0.16, 1, 0.3, 1);
  --fast: 160ms;
  --med: 240ms;
  --sweep-ms: 2400ms;   /* matches the 3D sweep in Scene.tsx */
}
// API shapes for the prioritization layer (D-050, api/routers/prioritize.py; contract in
// foundation/documents/prioritization.md → "API"). Unit = requirement × car line × market target (D-011).
import type { CheckpointId, TrackState } from "./types";
import type { ChoosableRung, Rung } from "./definition";

export type Band = "Must" | "Should" | "Could";
export const BANDS: Band[] = ["Must", "Should", "Could"];
export type Dimension = "customer" | "business" | "future";
export type GateResult = "pass" | "warn" | "fail" | "unchecked";
/** a gate may arrive as a bare result or with the checker's rationale */
export type GateValue = GateResult | { result: GateResult; rationale?: string | null; checked_by?: string | null };
export type ConfidenceLevel = "E1" | "E2" | "E3" | "E4";
export type ProposalCause = "new_fact" | "area_strengthened" | "market_trend" | "link_changed" | "pm_rung" | "weights_changed" | string;

export interface Factor {
  key: string;                 // customer_voice | satisfaction_gap | competitive_gap | market_weight | portfolio_leverage | future_relevance
  dimension: Dimension;
  value: number | null;        // 0–1, null when not available
  weight: number;              // nominal weight (prio-v1: 30 / 15 / 15 / 10 / 10 / 20)
  points: number;              // after renormalising over the available factors
  explanation: string;
  available: boolean;
}

export interface Modifier { key: string; points: number; why: string }   // effort | market_fit | …

export interface Confidence { level: ConfidenceLevel; mult: number; basis_mix: Record<string, number> }

export interface Confirmed { priority: Band; actor: string; at: string; rationale: string }

export interface Target {
  key: string;
  title: string;
  domain: string;
  zones: string[];
  area_key: string;
  line: string;
  market: string;
  score: number;
  base: number;
  band: Band;                  // the AI's proposed band (bundle-adjusted)
  own_band?: Band | null;      // the band on its own score when a bundle lifted it
  confirmed: Confirmed | null; // the PM's decision, if any
  rank: number;                // within line × market
  state: TrackState | "changed" | null;
  confidence: Confidence;
  factors: Factor[];
  modifiers: Modifier[];
  gates: { brand: GateValue; segment: GateValue; market: GateValue; feasibility: GateValue };
  bundle_id: string | null;
  flags: string[];             // e.g. "choose_jointly|energy|rq:…", "brand_blocked", "volume_conflict", "borrowed_voice"
  rung: { chosen: Rung | null; recommended: ChoosableRung; by?: "pm" | "ai" | "what_if" | null };
  rationale: string;
  prev: { score: number; band: Band } | null;
}

export interface Proposal {
  id: number | string;
  key: string;
  line: string;
  market: string;
  old_band: Band | null;
  proposed_band: Band;
  cause: ProposalCause;
  factor_delta: Record<string, number>;
  /** "pm" = against the PM-confirmed band, "parent" = against the AI's band at the earlier checkpoint */
  against?: "pm" | "parent" | null;
  status: "open" | "accepted" | "rejected";
  decided_by?: string | null;
  decided_at?: string | null;
  decision_rationale?: string | null;
  created_at?: string | null;
}

export interface PrioBundle { id: string; keys: string[]; band_by_target: Record<string, Band>; reason?: string }

export interface PrioRunInfo { id: number; finished_at: string | null; stats: Record<string, unknown> }

export interface PrioritizePayload {
  checkpoint: CheckpointId;
  ready: boolean;
  runs: { prioritize: PrioRunInfo | null; gate: PrioRunInfo | null };
  weights: {
    scheme?: string; version?: string | number; factors?: Record<string, number>; bands?: { Must: number; Should: number };
    /** prio-v1 version as named on the page (v1 = default); `id` = the shared weights_version row */
    id?: number | null; actor?: string | null; at?: string | null; rationale?: string | null; default?: boolean;
  } & Record<string, unknown>;
  /** the automatic re-score after PM actions (api/rescore.py) */
  rescore?: { state: "idle" | "running"; error?: string | null };
  labels: Record<string, string>;
  lines: string[];
  /** market codes; the API may give them per line */
  markets: string[] | Record<string, string[]>;
  targets: Target[];
  bundles: PrioBundle[];
  proposals: Proposal[];
  summary: { by_band: Partial<Record<Band, number>>; by_market: Record<string, Partial<Record<Band, number>>> };
}

export interface TargetDetail extends Target {
  history: { checkpoint: string; score: number; band: Band; rung?: string | null; confirmed?: Band | null }[];
  evidence: { comments?: number; study?: number; research?: number; options?: number; own_market?: boolean } & Record<string, unknown>;
}

export interface WhatIf {
  key: string; line: string; market: string; level: Rung;
  score: number; band: Band; base?: number;
  delta?: number;                                     // vs the stored score
  modifiers?: Modifier[];
  confidence?: Confidence;
  exposures: { key: string; title?: string; via: string; relation: string; note?: string }[];
}

export interface DecisionBody { key: string; line: string; market: string; priority: Band; rationale: string; actor: string; cp?: string }
export interface ProposalBody { verdict: "accept" | "reject"; rationale: string; actor: string }

/** "5 Series|US" — the target's place; with the key in front it identifies one target */
export const targetId = (t: Pick<Target, "key" | "line" | "market">) => `${t.key}|${t.line}|${t.market}`;
export const gateResult = (g: GateValue | undefined | null): GateResult => (!g ? "unchecked" : typeof g === "string" ? g : g.result);
export const gateWhy = (g: GateValue | undefined | null): string | null => (g && typeof g === "object" ? g.rationale ?? null : null);
// "Your decisions are challenged": a compact, non-modal line in the top-left HUD when the selected checkpoint has OPEN
// proposals against PM-confirmed bands (factor_delta.against = "pm"). Proposals against the AI's own earlier band stay
// passive marks. On arrival at a checkpoint the list is open and the line pulses once (white = attention; none under
// reduced motion); folded it stays a small count until every challenged decision is accepted or rejected. A row opens
// that target's inspector, where the proposal's Accept / Reject box sits.
import { useEffect, useMemo, useState } from "react";
import type { Proposal } from "@/lib/prioritize";
import type { LineName } from "@/lib/definition";
import { useCheckpoint } from "@/state/checkpoint";
import { setView } from "../definition/store";
import { BandMark } from "./marks";
import { CAUSE_LABEL, CP_LABEL, openProposals, type PrioData } from "./data";
import { selectTarget, setP, useP } from "./store";

export function Challenged({ pd }: { pd: PrioData }) {
  const { cp } = useCheckpoint();
  useP((s) => s.pendingProposals);   // an optimistic verdict removes its row at once
  const list = pd.sample ? [] : openProposals(pd.data).filter((p) => p.against === "pm");
  const title = useMemo(() => new Map(pd.data.targets.map((t) => [t.key, t.title])), [pd.data.targets]);
  const [open, setOpen] = useState(true);
  useEffect(() => { setOpen(true); }, [cp]);   // arriving at a checkpoint opens the list again
  if (!list.length) return null;
  const at = CP_LABEL[cp] ?? cp;
  const go = (p: Proposal) => {
    setView({ line: p.line as LineName });
    setP((s) => ({ market: { ...s.market, [p.line]: p.market }, view: "skyline" }));
    selectTarget(p.key);
  };
  return (
    <section className="pchal" key={cp} aria-label="Challenged decisions" aria-live="polite">
      <button className="pchal-head" aria-expanded={open} onClick={() => setOpen((o) => !o)}>
        <i className="pchal-dot" aria-hidden />
        <span className="num">{list.length}</span>
        <span>{list.length === 1 ? "of your decisions is" : "of your decisions are"} challenged at {at}</span>
      </button>
      {open && (
        <ul className="pchal-list">
          {list.map((p) => (
            <li key={p.id}>
              <button onClick={() => go(p)} title="Open: accept or reject">
                <span className="pchal-title">{title.get(p.key) ?? p.key}</span>
                <span className="label">{p.line} · {p.market}</span>
                <span className="pchal-move">
                  <BandMark band={p.old_band} color="var(--ink-2)" size="sm" pm />{p.old_band ?? "–"}
                  <span aria-hidden>→</span>
                  <BandMark band={p.proposed_band} color="var(--ink)" size="sm" />{p.proposed_band}
                </span>
                <span className="label">{CAUSE_LABEL[p.cause] ?? p.cause}</span>
              </button>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}
// The PM's position and challenges to it, shared by the skyline, the matrix and the list (page 4): a confirmed band is
// the one blue mark ("M ✓"); an open proposal against it is white attention ("!", "AI: Should ▼ · cause").
import type { Band, PrioritizePayload, Proposal, Target } from "@/lib/prioritize";
import { openProposals, pmBand } from "./data";

export const BAND_RANK: Record<Band, number> = { Must: 0, Should: 1, Could: 2 };
export interface Challenge { band: Band; from: Band; cause: string }

/** Open proposal against the PM-confirmed band of this target, if any. */
export function challengeOf(d: PrioritizePayload, t: Target): Proposal | null {
  if (!pmBand(t)) return null;
  return openProposals(d).find((p) => p.against === "pm" && p.key === t.key && p.line === t.line && p.market === t.market) ?? null;
}
export const arrow = (to: Band, from: Band | null) => (from && BAND_RANK[to] < BAND_RANK[from] ? "▲" : "▼");
/* Page 4: the PM's position and challenges to it (pm.ts). Blue = the PM's confirmed band, the only blue on the page;
   white = attention (a challenged decision). No amber. */
.psky-pm {
  display: inline-flex; align-items: center; height: 15px; padding: 0 5px; margin-left: 2px; border-radius: 3px; background: var(--sweep-hi);
  color: #fff; font-size: 10px; font-weight: 600; letter-spacing: 0.02em; box-shadow: 0 0 0 2px var(--sweep-wash);
}
.psky-chal { display: inline-flex; align-items: center; gap: 4px; margin-left: 4px; font-size: 10px; color: var(--ink); white-space: nowrap; }
.psky-chal b, .ptag-chal {
  display: inline-grid; place-items: center; width: 14px; height: 14px; border-radius: 50%; background: var(--ink); color: #000;
  font-size: 10px; font-weight: 700; line-height: 1;
}
.psky-cap:has(.psky-chal) { box-shadow: inset 0 0 0 1px rgba(242, 244, 247, 0.55); }
.ptag-pmok { color: var(--sweep-hi); font-size: var(--t-micro); font-weight: 600; letter-spacing: 0.02em; white-space: nowrap; }
.pmatrix-chal { display: inline-flex; align-items: center; gap: 3px; font-size: 10px; color: var(--ink); }
.pmatrix-ok { color: var(--sweep-hi); font-size: 10px; font-weight: 600; }
// Page 4 data: the live prioritize payload when the stage has run at this checkpoint, the sample fixture until then
// (polled, so the page switches to live data on its own), plus the PM's writes (decision, proposal verdict).
import { useMemo } from "react";
import { useMutation, useQuery } from "@tanstack/react-query";
import { api, getActor, queryClient } from "@/lib/api";
import { useCheckpoint } from "@/state/checkpoint";
import type { Rung } from "@/lib/definition";
import type { Band, PrioritizePayload, Proposal, Target, TargetDetail, WhatIf } from "@/lib/prioritize";
import { BAND_AT, FACTORS, fixtureDetail, fixtureFor, fixtureWhatIf } from "./fixture";
import { getP, setP } from "./store";
import { trackRescore } from "./rescore";

export interface PrioData { data: PrioritizePayload; sample: boolean; why: string | null; pending: boolean }

export function usePrioritize(): PrioData {
  const { cp } = useCheckpoint();
  const q = useQuery({
    queryKey: ["prioritize", cp],
    queryFn: () => api.get<PrioritizePayload>(`/api/prioritize?cp=${cp}`),
    retry: false, staleTime: 15_000, placeholderData: (prev) => prev,
    refetchInterval: (s) => (s.state.data?.ready && s.state.data.checkpoint === cp ? false : 10_000),
  });
  const fx = useMemo(() => fixtureFor(cp), [cp]);
  return useMemo(() => {
    const live = q.data?.ready && q.data.checkpoint === cp && q.data.targets?.length ? q.data : null;
    if (live) return { data: live, sample: false, why: null, pending: false };
    const why = q.isError ? "Prioritize API not available" : q.data && !q.data.ready ? "The prioritize stage has not run at this checkpoint" : "Waiting for the API";
    return { data: fx, sample: true, why, pending: q.isPending };
  }, [q.data, q.isError, q.isPending, cp, fx]);
}

/* --------------------------------------------------------------------------------------------- derived */
export const bandsAt = (d: PrioritizePayload) => ({ Must: d.weights?.bands?.Must ?? BAND_AT.Must, Should: d.weights?.bands?.Should ?? BAND_AT.Should });
const MARKET_ORDER = ["US", "EU", "CN", "JP", "RoW"];
export function marketsOf(d: PrioritizePayload, line: string): string[] {
  const given = Array.isArray(d.markets) ? null : d.markets?.[line];
  const found = [...new Set(d.targets.filter((t) => t.line === line).map((t) => t.market))];
  const list = given?.length ? [...given, ...found.filter((m) => !given.includes(m))] : found;
  return list.sort((a, b) => (MARKET_ORDER.indexOf(a) + 99) % 99 - (MARKET_ORDER.indexOf(b) + 99) % 99);
}
export function linesOf(d: PrioritizePayload): string[] {
  const found = new Set(d.targets.map((t) => t.line));
  return ["1 Series", "5 Series", "7 Series"].filter((l) => found.has(l));
}
export const tid = (t: Pick<Target, "key" | "line" | "market">) => `${t.key}|${t.line}|${t.market}`;

/** The band the page shows: the PM's (optimistic first), else the AI's proposed band. */
export function shownBand(t: Target): Band {
  return getP().pending[tid(t)] ?? t.confirmed?.priority ?? t.band;
}
/** The PM's band, if decided (optimistic first). */
export function pmBand(t: Target): Band | null {
  return getP().pending[tid(t)] ?? t.confirmed?.priority ?? null;
}

export interface Flag { kind: string; via?: string; partner?: string; band?: string; raw: string }
export function parseFlags(t: Target): Flag[] {
  return t.flags.map((raw) => {
    const [kind, a, b] = raw.split("|");
    if (kind === "choose_jointly") return { kind, via: a, partner: b, raw };
    if (kind === "bundle_band") return { kind, band: a, raw };
    return { kind, raw };
  });
}
export const isBlocked = (t: Target) => t.flags.includes("brand_blocked") || (typeof t.gates?.brand === "string" ? t.gates.brand === "fail" : t.gates?.brand?.result === "fail");

export const FLAG_LABEL: Record<string, string> = {
  choose_jointly: "Choose jointly", brand_blocked: "Brand fit blocks approval", borrowed_voice: "Borrowed customer voice",
  volume_conflict: "BMW vs. public volume conflict", bundle_band: "Band shared with its bundle",
};
export const flagLabel = (k: string) => FLAG_LABEL[k] ?? k.replace(/_/g, " ");
export const CAUSE_LABEL: Record<string, string> = {
  new_fact: "New benchmark fact", area_strengthened: "Customer evidence moved", market_trend: "Market trend",
  link_changed: "Linked requirement moved", pm_rung: "PM changed the rung", weights_changed: "PM changed the weights",
};
export const FACTOR_LABEL: Record<string, string> = Object.fromEntries(FACTORS.map((f) => [f.key, f.label]));
export const factorLabel = (k: string) => FACTOR_LABEL[k] ?? k.replace(/_/g, " ");
export const DIM_LABEL = { customer: "Customer", business: "Business", future: "Future" } as const;
export const CP_LABEL: Record<string, string> = { cp1: "JAN 26", cp2: "JUL 26" };

/** Requirements whose shown band differs between the markets of one line (D-011: markets are different customers). */
export function disagreements(d: PrioritizePayload, line: string): Set<string> {
  const by = new Map<string, Set<Band>>();
  for (const t of d.targets) if (t.line === line) by.set(t.key, (by.get(t.key) ?? new Set()).add(shownBand(t)));
  return new Set([...by].filter(([, s]) => s.size > 1).map(([k]) => k));
}

export function openProposals(d: PrioritizePayload): Proposal[] {
  const pend = getP().pendingProposals;
  return d.proposals.filter((p) => p.status === "open" && !pend[String(p.id)]);
}

/* --------------------------------------------------------------------------------------------- reads */
export function useTargetDetail(t: Target | null, pd: PrioData) {
  const { cp } = useCheckpoint();
  const live = !pd.sample;
  const q = useQuery({
    queryKey: ["prioritize-target", t?.key, t?.line, t?.market, cp],
    queryFn: () => api.get<TargetDetail>(`/api/prioritize/target/${encodeURIComponent(t!.key)}?line=${encodeURIComponent(t!.line)}&market=${encodeURIComponent(t!.market)}&cp=${cp}`),
    enabled: !!t && live, retry: false, staleTime: 15_000,
  });
  return useMemo<TargetDetail | null>(() => {
    if (!t) return null;
    if (live) return q.data ? { ...t, ...q.data } : { ...t, history: [], evidence: {} };
    return fixtureDetail(t);
  }, [t, live, q.data]);
}

export function useWhatIf(t: Target | null, level: Rung | null, pd: PrioData) {
  const { cp } = useCheckpoint();
  const live = !pd.sample;
  const q = useQuery({
    queryKey: ["prioritize-whatif", t?.key, t?.line, t?.market, level, cp],
    queryFn: () => api.get<WhatIf>(`/api/prioritize/what-if?key=${encodeURIComponent(t!.key)}&line=${encodeURIComponent(t!.line)}&market=${encodeURIComponent(t!.market)}&level=${level}&cp=${cp}`),
    enabled: !!t && !!level && live, retry: false, staleTime: 60_000,
  });
  return useMemo(() => {
    if (!t || !level) return { data: null as WhatIf | null, error: null as Error | null, pending: false };
    if (live) return { data: q.data ?? null, error: (q.error as Error) ?? null, pending: q.isPending };
    const title = (k: string) => pd.data.targets.find((x) => x.key === k)?.title;
    return { data: fixtureWhatIf(t, level, title), error: null, pending: false };
  }, [t, level, live, q.data, q.error, q.isPending, pd.data]);
}

/* --------------------------------------------------------------------------------------------- writes */
export function useDecision(pd: PrioData) {
  const { cp } = useCheckpoint();
  return useMutation({
    mutationFn: async (b: { key: string; line: string; market: string; priority: Band; rationale: string }) => {
      setP((s) => ({ pending: { ...s.pending, [`${b.key}|${b.line}|${b.market}`]: b.priority } }));
      if (pd.sample) return { sample: true };
      return api.post("/api/prioritize/decision", { ...b, actor: getActor(), cp });
    },
    onError: (_e, b) => setP((s) => { const p = { ...s.pending }; delete p[`${b.key}|${b.line}|${b.market}`]; return { pending: p }; }),
    onSuccess: async (r, b) => {
      if (pd.sample) return;
      await queryClient.invalidateQueries({ queryKey: ["prioritize", cp] });
      await queryClient.invalidateQueries({ queryKey: ["prioritize-target", b.key] });
      void trackRescore(r);   // the server re-scores the later checkpoints against this band
      setP((s) => { const p = { ...s.pending }; delete p[`${b.key}|${b.line}|${b.market}`]; return { pending: p }; });
    },
  });
}

export function useProposalVerdict(pd: PrioData) {
  const { cp } = useCheckpoint();
  return useMutation({
    mutationFn: async ({ p, verdict, rationale }: { p: Proposal; verdict: "accept" | "reject"; rationale: string }) => {
      setP((s) => ({
        pendingProposals: { ...s.pendingProposals, [String(p.id)]: verdict },
        // accepting a proposal is a PM decision on that band
        pending: verdict === "accept" ? { ...s.pending, [`${p.key}|${p.line}|${p.market}`]: p.proposed_band } : s.pending,
      }));
      if (pd.sample) return { sample: true };
      return api.post(`/api/prioritize/proposal/${encodeURIComponent(String(p.id))}`, { verdict, rationale, actor: getActor() });
    },
    onError: (_e, { p }) => setP((s) => {
      const pp = { ...s.pendingProposals }; delete pp[String(p.id)];
      const pend = { ...s.pending }; delete pend[`${p.key}|${p.line}|${p.market}`];
      return { pendingProposals: pp, pending: pend };
    }),
    onSuccess: async (r, { p }) => {
      if (pd.sample) return;
      await queryClient.invalidateQueries({ queryKey: ["prioritize", cp] });
      void trackRescore(r);
      setP((s) => {
        const pp = { ...s.pendingProposals }; delete pp[String(p.id)];
        const pend = { ...s.pending }; delete pend[`${p.key}|${p.line}|${p.market}`];
        return { pendingProposals: pp, pending: pend };
      });
    },
  });
}

