405	              {blocked && <span className="psky-blocked" title="Brand fit fails: approval blocked" aria-label="blocked by brand fit" />}
406	              <span className="psky-num">{Math.round(t.score)}</span>
407	              {delta !== 0 && Math.abs(delta) >= 1 && <span className="psky-delta">{delta > 0 ? "+" : "−"}{Math.abs(Math.round(delta))}</span>}
408	              {proposal && <span className="psky-prop" aria-label={`AI proposes ${proposal}`}>{proposal === "Must" || (proposal === "Should" && band === "Could") ? "▲" : "▼"}</span>}
409	              {pm && <span className="psky-pm" aria-label={`PM confirmed ${pm}`}>{pm[0]} ✓</span>}
410	              {challenge && (
411	                <span className="psky-chal" aria-label={`AI proposes ${challenge.band}, ${challenge.cause}`}>
412	                  <b>!</b>AI: {challenge.band} {BAND_RANK[challenge.band] < BAND_RANK[challenge.from] ? "▲" : "▼"} · {challenge.cause}
413	                </span>
414	              )}
415	            </div>
416	          </Html>
417	        )}
418	      </group>
419	    </group>
420	  );
421	});
422	
423	/* ------------------------------------------------------------------------------------------- label collisions */
424	type Register = (key: string, prio: number) => (el: HTMLElement | null) => void;
425	function useCollisions(): Register {
426	  const labels = useRef(new Map<string, { el: HTMLElement; prio: number }>());
427	  const tick = useRef(0);
428	  const register = useCallback<Register>((key, prio) => (el) => {
429	    if (el) labels.current.set(key, { el, prio }); else labels.current.delete(key);
430	  }, []);
431	  useFrame(() => {
432	    if (tick.current++ % 6) return;
433	    const placed: DOMRect[] = [];
434	    for (const { el, prio } of [...labels.current.values()].sort((a, b) => b.prio - a.prio)) {
435	      const r = el.getBoundingClientRect();
436	      if (!r.width) continue;
437	      const hit = prio < 1e9 && placed.some((q) => r.left < q.right + 2 && r.right > q.left - 2 && r.top < q.bottom + 1 && r.bottom > q.top - 1);
438	      el.toggleAttribute("data-collide", hit);
439	      if (!hit) placed.push(r);
440	    }
441	  });
442	  return register;
443	}
444	
445	/* ------------------------------------------------------------------------------------------- camera */
446	// An elevated three-quarter view of the whole ring, centred on screen; opening a priority or the panel leaves it
447	// where it is. The nav pad's Reset re-plans the same flight.
448	
449	function useSkylineCamera(active: boolean, reduced: boolean, nav?: MutableRefObject<NavInput>) {
450	  const controls = useThree((s) => s.controls) as unknown as Orbit | null;
451	  const camera = useThree((s) => s.camera);
452	  const aspect = useThree((s) => s.size.width / Math.max(1, s.size.height));
453	  const flight = useRef<{ t0: number; fromP: THREE.Vector3; fromT: THREE.Vector3; toP: THREE.Vector3; toT: THREE.Vector3; dur: number } | null>(null);
454	  const lastReset = useRef(nav?.current.reset ?? 0);
455	  const plan = useCallback((dur = 1.6) => {
456	    if (!controls) return;
457	    const pull = aspect < 1.3 ? Math.min(2.2, Math.pow(1.3 / aspect, 0.9)) : 1;
458	    const tgt = new THREE.Vector3(0, 0.35, 0);
459	    const dir = new THREE.Vector3(0.6, 0.72, -0.72).normalize();
460	    const p = tgt.clone().add(dir.multiplyScalar(10.2 * pull));
461	    flight.current = { t0: -1, fromP: camera.position.clone(), fromT: controls.target.clone(), toP: p, toT: tgt, dur: reduced ? 0 : dur };
462	  }, [controls, camera, aspect, reduced]);
463	  useEffect(() => {
464	    if (!active) { flight.current = null; return; }
465	    plan();
466	  }, [active, plan]);
467	  useFrame(({ clock }) => {
468	    if (nav && nav.current.reset !== lastReset.current) { lastReset.current = nav.current.reset; if (active) plan(); }
469	    const f = flight.current;
470	    if (!f || !controls) return;
471	    if (f.t0 < 0) f.t0 = clock.elapsedTime;
472	    const p = f.dur ? Math.min(1, (clock.elapsedTime - f.t0) / f.dur) : 1;
473	    glide(f.fromP, f.fromT, f.toP, f.toT, easeOut(p), camera.position, controls.target);
474	    controls.update();
475	    if (p >= 1) flight.current = null;
476	  });
477	}
478

