  jul?: Partial<Record<number, number>>; pm?: Band; pmWhy?: string; julOnly?: boolean; chosen?: Rung; rec?: "threshold" | "target" | "stretch";
  flags?: string[];
}
type Row = [string, string, string, F6, Opt?];
