62	
63	  const targets = useMemo(() => data.targets.filter((t) => t.line === line && t.market === market), [data, line, market]);
64	  const sel = selected ? targets.find((t) => t.key === selected) ?? null : null;
65	
66	  // the list and inspector sit behind the Priorities pill; picking a column opens it, closing it deselects
