75	    const onKey = (e: KeyboardEvent) => {
76	      if (e.metaKey || e.ctrlKey || e.altKey || (e.target instanceof HTMLElement && /^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName))) return;
77	      if (e.key === "Escape") {
78	        const s = getP();
79	        if (s.selected) selectTarget(null);
