85	      if (e.key === "[" || e.key === "]") {
86	        const i = markets.indexOf(market) + (e.key === "]" ? 1 : -1);
87	        if (i >= 0 && i < markets.length) setMarket(markets[i]);
88	      }
89	    };
90	    window.addEventListener("keydown", onKey);
91	    return () => window.removeEventListener("keydown", onKey);
92	  });
93	  useEffect(() => () => setP({ hover: null, hoverPos: null }), []);
94	  const weightsOpen = useWeightsOpen();
95	  useEffect(() => { if (view === "matrix") setWeightsOpen(false); }, [view]);   // the matrix and the weights share the left
96	  useEffect(() => () => setWeightsOpen(false), []);
97	  const rescoring = useRescoring() || data.rescore?.state === "running";
98	
99	  /* readout */
100	  const counts = { Must: 0, Should: 0, Could: 0 } as Record<Band, number>;
101	  for (const t of targets) counts[shownBand(t)]++;
102	  const props = openProposals(data).filter((p) => p.line === line && p.market === market);
103	  const joint = new Set(targets.flatMap((t) => parseFlags(t).filter((f) => f.kind === "choose_jointly").map((f) => [t.key, f.partner].sort().join("~")))).size;
104	  const blocked = targets.filter(isBlocked).length;
105	  const disagree = disagreements(data, line);
106	  const confirmed = targets.filter((t) => pmBand(t)).length;
107	  // the matrix hangs right under this corner, however tall it is (sample note, wrapped controls)
108	  const hudRef = useRef<HTMLDivElement>(null);
109	  useEffect(() => {
110	    const el = hudRef.current;
