112	    const put = () => document.documentElement.style.setProperty("--phud-bottom", `${Math.round(el.getBoundingClientRect().bottom)}px`);
113	    put();
114	    const ro = new ResizeObserver(put);
115	    ro.observe(el);
116	    window.addEventListener("resize", put);
117	    return () => { ro.disconnect(); window.removeEventListener("resize", put); };
118	  }, []);
119	
120	  return (
121	    <>
122	      <div className="hud-tl phud" ref={hudRef}>
123	        {/* the band numbers stay narrow enough to sit left of the top bar, like pages 1–3; the rest goes under them */}
124	        <dl className="preadout" aria-label={`Priorities for ${line} in ${market}`}>
125	          {BANDS.map((b) => (
126	            <div key={b} className="preadout-band">
127	              <dt className="label"><BandMark band={b} color="var(--ink)" size="sm" />{b}</dt>
