134	          <div><dt className="label">choose jointly</dt><dd className="num">{joint}</dd></div>
135	          <div><dt className="label">blocked</dt><dd className="num">{blocked}</dd></div>
136	          {markets.length > 1 && <div><dt className="label">markets disagree</dt><dd className="num">{disagree.size}</dd></div>}
137	        </dl>
138	        <Challenged pd={pd} />
139	        <p className="pnote label">{targets.length} targets · {confirmed} confirmed by the PM · {weightsNote(data.weights)} · market weight {data.labels?.market_weight ?? "stylized (Q-015)"}{rescoring && <span className="prescore" role="status"> · re-scoring…</span>}</p>
140	        <div className="pcontrols">
141	          <div className="dseg" role="radiogroup" aria-label="Car line">
142	            {lines.map((l) => <button key={l} role="radio" aria-checked={line === l} onClick={() => setView({ line: l as LineName })}>{l}</button>)}
