145	            <span className="dseg-name label">Market</span>
146	            {markets.map((m) => <button key={m} role="radio" aria-checked={market === m} onClick={() => setMarket(m)} title={MARKET_NAME[m] ?? m}>{m}</button>)}
147	          </div>
148	          <div className="dseg" role="radiogroup" aria-label="View">
149	            <button role="radio" aria-checked={view === "skyline"} onClick={() => setP({ view: "skyline" })}>Skyline</button>
150	            <button role="radio" aria-checked={view === "matrix"} onClick={() => setP({ view: "matrix" })}>Matrix</button>
151	          </div>
152	          <WeightsButton pd={pd} />
153	        </div>
154	        {pd.sample && <p className="dsample" role="status"><b>Sample data</b> {pd.why}. Live priorities replace it as soon as the stage has run.</p>}
155	      </div>
156	
157	      {view === "matrix" && <Matrix pd={pd} line={line} markets={markets} market={market} onMarket={setMarket} />}
158	      {weightsOpen && view !== "matrix" && <WeightsPanel pd={pd} />}
159	      {showPanel && (sel ? <Inspector key={tid(sel)} pd={pd} t={sel} markets={markets} onMarket={setMarket} /> : <RankedList pd={pd} targets={targets} line={line} market={market} />)}
160	      <TargetHover pd={pd} line={line} market={market} />
161	      <Dock mode="prioritize" sel={null} guide={<PrioritizeGuide sel={sel} view={view} />} agent={<AgentPanel layer="prioritize" />} running={!!activity.data?.running} />
162	    </>
163	  );
