166	/* --------------------------------------------------------------------------------------------- ranked list */
167	function RankedList({ pd, targets, line, market }: { pd: PrioData; targets: Target[]; line: string; market: string }) {
168	  const selected = useP((s) => s.selected);
169	  const sorted = [...targets].sort((a, b) => b.score - a.score);
170	  const proposals = new Map(openProposals(pd.data).filter((p) => p.line === line && p.market === market).map((p) => [p.key, p]));
171	  return (
172	    <nav className="dlist plist" id="priorities-panel" aria-label="Priorities">
173	      <p className="dlist-head"><span className="sheet-layer">Priorities · {line} · {market}</span><span className="label">Score</span></p>
174	      {BANDS.map((b) => {
175	        // challenged PM decisions first (white !), then by score
176	        const items = sorted.filter((t) => shownBand(t) === b).sort((x, y) => Number(!!challengeOf(pd.data, y)) - Number(!!challengeOf(pd.data, x)));
177	        if (!items.length) return null;
178	        return (
179	          <section key={b}>
180	            <h3 className="dlist-domain plist-band"><BandMark band={b} color="var(--ink-2)" size="sm" />{b}<span>{items.length}</span></h3>
181	            <ul>
182	              {items.map((t) => {
183	                const pm = pmBand(t);
184	                const flags = parseFlags(t);
185	                const p = proposals.get(t.key);
186	                const d = t.prev ? t.score - t.prev.score : 0;
187	                return (
188	                  <li key={t.key}>
189	                    <button className="dlist-row plist-row" aria-current={selected === t.key ? "true" : undefined}
190	                            onClick={() => selectTarget(selected === t.key ? null : t.key)}
191	                            onPointerEnter={() => setP({ hover: t.key })} onPointerLeave={() => setP({ hover: null })}>
192	                      <span className="plist-rank">{t.rank}</span>
193	                      <BandMark band={shownBand(t)} color={domainColor(t.domain)} />
194	                      <span className="dlist-title">{t.title}</span>
195	                      <span className="plist-tags">
196	                        {challengeOf(pd.data, t) && <b className="ptag-chal" title={`AI proposes ${challengeOf(pd.data, t)!.proposed_band}`}>!</b>}
197	                        {pm && <span className="ptag-pmok">PM ✓</span>}
198	                        {isBlocked(t) && <span className="psky-blocked" title="Brand fit blocks approval" />}
199	                        {flags.some((f) => f.kind === "choose_jointly") && <span className="ptag" data-dashed="" title="Choose jointly">joint</span>}
200	                        {p && <span className="ptag" title={`AI proposes ${p.proposed_band}`}>→ {p.proposed_band}</span>}
201	                        <span className="plist-conf" title="Confidence">{t.confidence.level}</span>
202	                      </span>
203	                      <span className="dlist-val">{fmt(t.score)}{Math.abs(d) >= 1 && <Arrow d={d} />}</span>
204	                    </button>
205	                  </li>
206	                );
207	              })}
208	            </ul>
209	          </section>
210	        );
211	      })}
212	    </nav>
213	  );
214	}
