217	function TargetHover({ pd, line, market }: { pd: PrioData; line: string; market: string }) {
218	  const hover = useP((s) => s.hover);
219	  const pos = useP((s) => s.hoverPos);
220	  const selected = useP((s) => s.selected);
221	  if (!hover || !pos || hover === selected) return null;
222	  const t = pd.data.targets.find((x) => x.key === hover && x.line === line && x.market === market);
223	  if (!t) return null;
224	  const left = Math.min(pos.x + 16, window.innerWidth - 336), top = Math.min(pos.y + 16, window.innerHeight - 140);
225	  return (
226	    <div className="hovercard" style={{ left, top }} role="tooltip">
227	      <p>{t.title}</p>
228	      <div className="hovercard-meta">
229	        <BandMark band={shownBand(t)} color={domainColor(t.domain)} size="sm" /><span>{shownBand(t)} · {fmt(t.score)}</span>
230	        <span>#{t.rank} in {line} · {market}</span><span>{t.confidence.level}</span>
231	      </div>
232	      <div className="hovercard-meta"><span>{DOMAIN_LABEL[t.domain] ?? t.domain}</span>{t.prev && <span>JAN {fmt(t.prev.score)} → JUL {fmt(t.score)}</span>}</div>
233	    </div>
234	  );
