237	/* --------------------------------------------------------------------------------------------- matrix */
238	// Rows grouped by domain, one column per market of the line; each cell the band mark (domain hue) with its score,
239	// an arrow where JAN → JUL moved it, a blue ring where the PM confirmed it. A white tick marks rows whose band differs
240	// between markets.
241	function Matrix({ pd, line, markets, market, onMarket }: { pd: PrioData; line: string; markets: string[]; market: string; onMarket: (m: string) => void }) {
242	  const { position } = useCheckpoint();
243	  const selected = useP((s) => s.selected);
244	  const hover = useP((s) => s.hover);
245	  const onLine = pd.data.targets.filter((t) => t.line === line);
246	  const cell = new Map(onLine.map((t) => [tid(t), t]));
247	  const reqs = [...new Map(onLine.map((t) => [t.key, t])).values()];
248	  const best = (k: string) => Math.max(...onLine.filter((t) => t.key === k).map((t) => t.score));
249	  const groups = DOMAIN_ORDER.map((d) => ({ d, items: reqs.filter((r) => r.domain === d).sort((a, b) => best(b.key) - best(a.key)) })).filter((g) => g.items.length);
250	  const disagree = disagreements(pd.data, line);
251	  const props = new Set(openProposals(pd.data).map((p) => `${p.key}|${p.line}|${p.market}`));
252	  return (
253	    <section className="pmatrix" aria-label={`Market by requirement, ${line}`}>
254	      <header className="pmatrix-head">
255	        <span className="sheet-layer">Market × requirement · {line}</span>
256	        <span className="pmatrix-legend label">
257	          <span><BandMark band="Must" color="var(--ink-2)" size="sm" />Must</span><span><BandMark band="Should" color="var(--ink-2)" size="sm" />Should</span>
258	          <span><BandMark band="Could" color="var(--ink-2)" size="sm" />Could</span><span><i className="pmatrix-pm" />PM confirmed</span>
259	          {position > 1 && <span>▲▼ since JAN</span>}<span><i className="pmatrix-dis" />markets disagree</span>
260	        </span>
261	      </header>
262	      <div className="pmatrix-grid" style={{ ["--m" as string]: markets.length }}>
263	        <div className="pmatrix-row pmatrix-cols" aria-hidden>
264	          <span />
265	          {markets.map((m) => <button key={m} className="pmatrix-mkt" aria-pressed={m === market} onClick={() => onMarket(m)}>{m}</button>)}
266	          <span />
267	        </div>
268	        {groups.map(({ d, items }) => (
269	          <div key={d} className="pmatrix-group">
270	            <h3 className="dlist-domain"><i style={{ background: domainColor(d) }} aria-hidden />{DOMAIN_LABEL[d] ?? d}<span>{items.length}</span></h3>
271	            {items.map((r) => (
272	              <div key={r.key} className="pmatrix-row" data-on={selected === r.key ? "" : undefined} data-hover={hover === r.key ? "" : undefined}
273	                   onPointerEnter={() => setP({ hover: r.key })} onPointerLeave={() => setP({ hover: null })}>
274	                <button className="pmatrix-title" onClick={() => selectTarget(selected === r.key ? null : r.key)}>{r.title}</button>
275	                {markets.map((m) => {
276	                  const t = cell.get(`${r.key}|${line}|${m}`);
277	                  if (!t) return <span key={m} className="pmatrix-cell" data-empty="">·</span>;
278	                  const d = t.prev && position > 1 ? t.score - t.prev.score : 0;
279	                  const b = shownBand(t);
280	                  return (
281	                    <button key={m} className="pmatrix-cell" data-current={m === market ? "" : undefined} title={`${m}: ${b} · ${fmt(t.score)}`}
282	                            onClick={() => { onMarket(m); selectTarget(r.key); }}>
283	                      <BandMark band={b} color={domainColor(t.domain)} pm={!!pmBand(t)} />
284	                      <span className="pmatrix-score">{fmt(t.score)}</span>
285	                      {(Math.abs(d) >= 3 || (t.prev && t.prev.band !== t.band && position > 1)) && <Arrow d={d} />}
286	                      {pmBand(t) && <span className="pmatrix-ok" aria-label="PM confirmed">✓</span>}
287	                      {(() => { const ch = challengeOf(pd.data, t); return ch
288	                        ? <span className="pmatrix-chal" title={`AI proposes ${ch.proposed_band} against your ${pmBand(t)}`}><b className="ptag-chal">!</b>{ch.proposed_band[0]}{arrow(ch.proposed_band, pmBand(t))}</span>
289	                        : props.has(tid(t)) && <span className="pmatrix-prop" title="Open AI proposal">P</span>; })()}
290	                    </button>
291	                  );
292	                })}
293	                <span className="pmatrix-dis" data-on={disagree.has(r.key) ? "" : undefined} aria-label={disagree.has(r.key) ? "markets disagree" : undefined} />
294	              </div>
295	            ))}
296	          </div>
297	        ))}
298	      </div>
299	    </section>
300	  );
301	}
