408	          <div className="dlinks-head">
409	            <span className="label">Bundle · prioritized together</span>
410	            <button className="dtext" aria-pressed={bundleOn === bundle.id} onClick={() => setP({ bundle: bundleOn === bundle.id ? null : bundle.id })}>{bundleOn === bundle.id ? "Hide bundle" : "Show bundle"}</button>
411	          </div>
412	          <BundleMembers t={t} bundle={bundle} targets={data.targets} />
413	          {bundle.reason && <p className="label">{bundle.reason}; the bundle shares its strongest member's band.</p>}
414	        </div>
415	      )}
416	
417	      {flags.filter((f) => f.kind !== "brand_blocked").length > 0 && (
418	        <div className="dblock">
419	          <span className="label">Flags</span>
420	          <ul className="pflags">
421	            {flags.filter((f) => f.kind !== "brand_blocked").map((f) => (
422	              <li key={f.raw}>
423	                <span className="ptag" data-dashed={f.kind === "choose_jointly" ? "" : undefined}>{flagLabel(f.kind)}{f.via ? ` · ${f.via}` : ""}</span>
424	                {f.kind === "choose_jointly" && f.partner && <button className="dlink-other" onClick={() => selectTarget(f.partner!)}>with {titleOf(f.partner)}</button>}
425	                {f.kind === "bundle_band" && <span className="label">scored {f.band} on its own</span>}
426	                {f.kind === "borrowed_voice" && <span className="label">no own-market comments; × 0.5 and capped (D-038)</span>}
427	              </li>
428	            ))}
429	          </ul>
430	        </div>
431	      )}
432	
433	      {(detail?.history?.length ?? 0) > 0 && (
434	        <div className="dblock">
435	          <span className="label">History</span>
436	          <ol className="phistory">
437	            {detail!.history.map((h) => (
438	              <li key={h.checkpoint}>
439	                <span className="phistory-cp">{CP_LABEL[h.checkpoint] ?? h.checkpoint}</span>
440	                <BandMark band={h.band} color={domainColor(t.domain)} size="sm" />
441	                <span className="phistory-s">{fmt(h.score)}</span>
442	                <span className="label">{h.band}{h.rung ? ` · ${h.rung}` : ""}{h.confirmed ? ` · PM ${h.confirmed}` : ""}</span>
443	              </li>
444	            ))}
445	          </ol>
446	        </div>
447	      )}
448	
449	      {proposal && <ProposalBlock pd={pd} p={proposal} />}
450	      <DecisionBlock pd={pd} t={t} bundled={!!bundle && bundle.keys.length > 1} />
451	    </aside>
452	  );
453	}
454	
455	function ProposalBlock({ pd, p }: { pd: PrioData; p: Proposal }) {
456	  const verdict = useProposalVerdict(pd);
457	  const [open, setOpen] = useState<"accept" | "reject" | null>(null);
458	  const [why, setWhy] = useState("");
459	  const deltas = Object.entries(p.factor_delta ?? {}).filter(([, v]) => v);
460	  const down = deltas.reduce((s, [, v]) => s + v, 0) < 0;
461	  return (
462	    <div className="dblock pproposal">
463	      <span className="label">AI proposal · JAN → JUL</span>
464	      <p className="pproposal-line"><BandMark band={p.old_band} color="var(--ink-2)" size="sm" />{p.old_band ?? "–"} <span aria-hidden>→</span> <BandMark band={p.proposed_band} color="var(--ink)" size="sm" />{p.proposed_band}
465	        <span className="label"> · {CAUSE_LABEL[p.cause] ?? p.cause}{p.cause === "area_strengthened" && down ? " (weaker)" : ""}</span></p>
466	      {deltas.length > 0 && <ul className="drail">{deltas.map(([k, v]) => <li key={k}>{factorLabel(k)} <b>{v > 0 ? "+" : "−"}{Math.abs(v)} pts</b></li>)}</ul>}
467	      {open ? (
468	        <form className="ladder-choose" onSubmit={(e) => { e.preventDefault(); if (why.trim().length >= 5) { verdict.mutate({ p, verdict: open, rationale: why.trim() }); setOpen(null); setWhy(""); } }}>
469	          <textarea rows={2} value={why} onChange={(e) => setWhy(e.target.value)} autoFocus placeholder={`Why ${open} this proposal? (required)`} aria-label="Rationale" />
470	          <div className="ladder-actions">
471	            <button type="submit" className="dbtn primary" disabled={why.trim().length < 5 || verdict.isPending}>{open === "accept" ? `Accept → ${p.proposed_band}` : "Reject"}</button>
472	            <button type="button" className="dbtn" onClick={() => setOpen(null)}>Cancel</button>
473	          </div>
474	        </form>
475	      ) : (
476	        <div className="dlink-actions">
477	          <button className="dtext" onClick={() => setOpen("accept")}>Accept</button>
478	          <button className="dtext" onClick={() => setOpen("reject")}>Reject</button>
479	        </div>
480	      )}
481	      {verdict.isError && <p className="derror">Not saved: {(verdict.error as Error).message}</p>}
482	    </div>
483	  );
484	}
485	
486	function DecisionBlock({ pd, t, bundled = false }: { pd: PrioData; t: Target; bundled?: boolean }) {
487	  const decide = useDecision(pd);
488	  const pm = pmBand(t);
489	  const [pick, setPick] = useState<Band | null>(null);
490	  const [why, setWhy] = useState("");
491	  const [lastWhy, setLastWhy] = useState("");
492	  const blocked = isBlocked(t);
493	  const send = () => {
494	    if (!pick || why.trim().length < 5) return;
495	    decide.mutate({ key: t.key, line: t.line, market: t.market, priority: pick, rationale: blocked ? `[brand-fit override] ${why.trim()}` : why.trim() });
496	    setLastWhy(why.trim()); setPick(null); setWhy("");
497	  };
498	  return (
499	    <div className="dblock pdecide">
500	      <span className="label">PM decision · {t.line} · {t.market}</span>
501	      {pm && (pm === t.confirmed?.priority
502	        ? <p className="ladder-why pm"><span className="label">PM</span>{pm} · {t.confirmed.actor}{t.confirmed.rationale ? ` · ${t.confirmed.rationale}` : ""}</p>
503	        : <p className="ladder-why pm"><span className="label">PM</span>{pm} · {getActor()} · {lastWhy || "just now"}</p>)}
504	      <p className="pdecide-scope">{pick ? <>You confirm <b>{pick}</b> for “{t.title}” in {t.line} · {t.market} only.</> : <>A decision applies to this requirement in {t.line} · {t.market} only.</>}
505	        {bundled ? " Bundle members keep their own decisions." : ""}</p>
506	      <div className="pdecide-bands" role="radiogroup" aria-label="Priority">
507	        {BANDS.map((b) => (
508	          <button key={b} role="radio" aria-checked={pick === b} data-pm={pm === b ? "" : undefined} onClick={() => setPick(pick === b ? null : b)}>
509	            <BandMark band={b} color={pm === b ? "var(--sweep-hi)" : "var(--ink)"} pm={pm === b} />{b}{t.band === b && <span className="ladder-ai">AI</span>}
510	          </button>
511	        ))}
512	      </div>
513	      {pick && (
514	        <form className="ladder-choose" onSubmit={(e) => { e.preventDefault(); send(); }}>
515	          <textarea rows={2} value={why} onChange={(e) => setWhy(e.target.value)} autoFocus aria-label="Rationale"
516	                    placeholder={blocked ? "Brand fit fails. Why override it? (required)" : `Why ${pick} for ${t.market}? (required)`} />
517	          <div className="ladder-actions">
518	            <button type="submit" className="dbtn primary" disabled={why.trim().length < 5 || decide.isPending}>{blocked ? `Override and confirm ${pick}` : `Confirm ${pick}`}</button>
519	            <button type="button" className="dbtn" onClick={() => setPick(null)}>Cancel</button>
520	          </div>
521	        </form>
522	      )}
523	      {decide.isError && <p className="derror">Not saved: {(decide.error as Error).message}</p>}
524	      {pd.sample && <p className="label">Sample data: decisions are kept in this view only.</p>}
525	    </div>
526	  );
527	}
528	
529

