src/screens/prioritize/weights.css:68:.pchal-dot { position: relative; align-self: center; width: 7px; height: 7px; border-radius: 50%; background: var(--ink); flex: none; }
src/screens/prioritize/weights.css:69:.pchal-dot::after { content: ""; position: absolute; inset: -4px; border-radius: 50%; box-shadow: 0 0 0 1.5px var(--ink); opacity: 0; animation: psky-pulse 1.6s var(--ease) 0.6s 1 both; }
src/screens/prioritize/weights.css:70:@media (prefers-reduced-motion: reduce) { .pchal-dot::after { animation: none; } }
