src/screens/prioritize/weights.css:76:.pchal-list button:hover { background: rgba(255, 255, 255, 0.07); }
src/screens/prioritize/weights.css:77:.pchal-title { font-size: 13px; color: var(--ink); max-width: 230px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
src/screens/prioritize/weights.css:78:.pchal-move { display: inline-flex; align-items: flex-end; gap: 5px; font-size: var(--t-label); color: var(--ink-2); }
src/screens/prioritize/prioritize.css:27:.parrow { font-size: 8px; margin-left: 4px; color: var(--ink); vertical-align: 1px; }
src/screens/prioritize/prioritize.css:28:.parrow[data-d="down"] { color: var(--ink-3); }
src/screens/prioritize/prioritize.css:158:.pproposal-line { display: flex; align-items: flex-end; gap: 6px; font-size: var(--t-body); color: var(--ink); }
.pstats { margin: -2px 0 0; display: flex; flex-wrap: wrap; gap: 4px 16px; pointer-events: none; }
.pstats > div { display: inline-flex; align-items: baseline; gap: 5px; flex-direction: row-reverse; }   /* number first, label after */
.pstats dd { margin: 0; font-size: 15px; color: var(--ink); }
.pstats dt { color: var(--ink-3); }
