.psky-cap[data-collide] { visibility: hidden !important; }
.psky-cap[data-hot] { color: var(--ink); z-index: 2; }
.psky-cap[data-hot] .psky-num { color: var(--ink); }
.psky-cap[data-on] { box-shadow: inset 0 0 0 1px var(--ink); }
.psky-cap[data-dim] { opacity: 0.35 !important; }
.psky-delta { font-size: 10px; color: var(--ink-3); }
.psky-prop { font-size: 8px; color: var(--ink); }
.psky-blocked, .plist-tags .psky-blocked { display: inline-block; width: 9px; height: 9px; border-radius: 50%; box-shadow: inset 0 0 0 1.2px var(--ink); position: relative; align-self: center; }
.psky-blocked::after { content: ""; position: absolute; left: 3.8px; top: 0.5px; width: 1.3px; height: 8px; background: var(--ink); transform: rotate(45deg); }
/* risers and fallers at a checkpoint change: one white ring (0ms under reduced motion) */
.psky-pulse { position: absolute; left: 50%; top: 50%; width: 14px; height: 14px; margin: -7px 0 0 -7px; border-radius: 50%; box-shadow: 0 0 0 1.5px var(--ink); opacity: 0; animation: psky-pulse 1.6s var(--ease) 1.2s 1 both; pointer-events: none; }
@keyframes psky-pulse { 0% { opacity: 0.95; transform: scale(1); } 100% { opacity: 0; transform: scale(3.2); } }
@media (prefers-reduced-motion: reduce) { .psky-pulse { display: none; } }
.psky-plane {
  padding: 1px 6px; border-radius: 4px; background: rgba(0, 0, 0, 0.6); font-size: var(--t-micro); font-weight: 600; letter-spacing: 0.08em;
  color: var(--ink-3); white-space: nowrap; pointer-events: none; user-select: none; text-transform: uppercase;
}

