// API shapes for page 5, Document (api/routers/document.py; foundation/documents/document.md): the deliverable — the
// traceable requirement list per car line × market at a checkpoint.
import type { CheckpointId } from "./types";
import type { Band, GateValue, Proposal } from "./prioritize";
import type { Acceptance, LadderRow, Metric } from "./definition";

export type DocProposal = Omit<Proposal, "status"> & { status: Proposal["status"] | "superseded"; checkpoint: string; explain?: string | null };
export type DocStatus = "confirmed" | "ai_proposal" | "open_proposal" | "open_proposal_against_pm";

export interface DocHeader {
  checkpoint: CheckpointId;
  label: string;
  cutoff: string;
  line: string;
  market: string;
  generated_at: string;
  run: { id: number; finished_at: string } | null;
  weights_version: number | string;
  scheme: string;
  band_thresholds: { Must: number; Should: number };
  lines: string[];
  markets_by_line: Record<string, string[]>;
  by_band: Partial<Record<Band, number>>;
  ai_by_band: Partial<Record<Band, number>>;
  count: number;
  confirmed: number;
  open_proposals: number;
}

export interface DocQuote { quote: string; source_id: number; external_id: string; market: string | null; line: string | null }
export interface DocEvidence {
  id: string;
  kind: string;
  text: string | null;
  url: string | null;
  tier: string | null;
  published: string | null;
  relation: string | null;
  quote: string | null;
  quotes?: DocQuote[];
}

export interface DocLink { key: string; title: string | null; relation: string; via: string | null; strength: number; rationale: string | null; source: "ai" | "pm"; status: string }
export interface DocHistory { checkpoint: CheckpointId; label: string; score: number; band: Band; rank: number; confirmed: Band | null }
export interface DocDecision { priority: Band; rationale: string; actor: string; at: string; checkpoint: string | null }
export interface DocFactor { key: string; label: string; dimension: string; weight: number; points: number; value: number | null; available: boolean; explanation: string }

export interface DocItem {
  key: string;
  id: string;
  number: number;
  version: number;
  title: string;
  statement: string | null;
  domain: string;
  area: { key: string; title?: string; need?: string; kind?: string } | null;
  horizon: string | null;
  horizon_year: number | null;
  kano: string | null;
  decision_type: string | null;
  today_status: string | null;
  req_status: string | null;
  metric: Metric | null;
  acceptance: Acceptance[];
  rung: { level: string | null; by: "pm" | "ai"; recommended: string | null; value?: number | null; text?: string | null; basis?: string | null; note?: string | null;
          source_ids?: string[]; choice: { level: string; rationale: string; actor: string; at: string } | null };
  ladder: LadderRow | null;
  priority: { band: Band; ai_band: Band; ai_score: number; base: number; rank: number; own_band: Band | null;
              confirmed: { priority: Band; actor: string; at: string; rationale: string } | null };
  status: DocStatus;
  open_proposal: DocProposal | null;
  rationale: string | null;
  factors: DocFactor[];
  modifiers: { key: string; points: number; why: string }[];
  effort: unknown;
  evidence: { level: string | null; comments: number | null; count: number; items: DocEvidence[]; trend_ids: string[] };
  assumptions: string[];
  gaps: string[];
  uncertainties: string[];
  flags: string[];
  links: DocLink[];
  gates: Record<string, GateValue>;
  track: string | null;
  prev: { score: number; band: Band; checkpoint: string } | null;
  history: DocHistory[];
  proposals: DocProposal[];
  decisions: DocDecision[];
}

export interface DocumentPayload { ready: boolean; header: DocHeader; items: DocItem[] }

export interface ChangeBrief { key: string; id: string; title: string; domain: string; band: Band; ai_band: Band; score: number }
export interface ChangesPayload {
  from: { checkpoint: CheckpointId; label: string };
  to: { checkpoint: CheckpointId; label: string };
  line: string;
  market: string;
  new: ChangeBrief[];
  removed: ChangeBrief[];
  moved: (ChangeBrief & { from: { ai_band: Band; score: number; confirmed: Band | null }; to: { ai_band: Band; score: number; confirmed: Band | null };
             direction: "up" | "down" | "same"; ai_band_changed: boolean; pm_band_changed: boolean })[];
  band_up: number;
  band_down: number;
  decisions: (DocDecision & { key: string; id: string; title: string })[];
  proposals: Record<"accepted" | "rejected" | "open" | "superseded", (DocProposal & { id_human: string; title: string })[]>;
}
/* Page 5, Document: a full-height reading sheet over page 4's scene, which sinks and dims behind it. Same world:
   true black field, Mona Sans, numerals lead, hairlines, no cards or shadows; sweep blue only for the PM's marks. */

/* the scene steps back: sink + dim over ~300 ms, no pointer on the canvas while the sheet is up */
.scan .scan-canvas { transition: opacity 300ms var(--ease), transform 300ms var(--ease); }
.scan[data-mode="document"] .scan-canvas { opacity: 0.3; transform: translateY(5vh) scale(0.97); pointer-events: none; }
.scan[data-mode="document"] :is(.ring-name, .ring-sub, .time-label, .ring-label, .theme-label, .area-label) { opacity: 0 !important; pointer-events: none; }
.scan[data-mode="document"] .navpad { display: none; }

.docsheet {
  position: fixed; z-index: 10; top: calc(var(--edge) + 48px); bottom: calc(var(--edge) + 128px + env(safe-area-inset-bottom, 0px));
  left: 50%; transform: translateX(-50%); width: min(1120px, calc(100vw - 2 * var(--edge)));
  overflow-y: auto; padding: 0 28px 40px; background: var(--field); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
  --feather: linear-gradient(to right, transparent, #000 18px, #000 calc(100% - 18px), transparent), linear-gradient(to bottom, #000 calc(100% - 28px), transparent);
  -webkit-mask-image: var(--feather); mask-image: var(--feather); -webkit-mask-composite: source-in; mask-composite: intersect;
  animation: doc-in 300ms var(--ease); scrollbar-width: thin; scrollbar-color: var(--hair-2) transparent;
}
@keyframes doc-in { from { opacity: 0; transform: translate(-50%, 14px); } }
@media (prefers-reduced-motion: reduce) {
  .docsheet { animation: none; }
  .scan .scan-canvas { transition: none; }
}
@media (max-width: 760px) { .docsheet { width: calc(100vw - 32px); padding: 0 12px 40px; } }

.docsheet .num { font-variation-settings: "wdth" 118; font-weight: 300; font-feature-settings: "tnum" 1; }
.doc-small { font-size: var(--t-micro); color: var(--ink-3); line-height: 1.45; }
.doc-kicker { display: inline-flex; align-items: center; gap: 6px; font-size: var(--t-micro); letter-spacing: 0.02em; color: var(--ink-3); }
.doc-kicker i { width: 7px; height: 7px; border-radius: 50%; }

/* ------------------------------------------------------------------------------------------- top */
.doc-top { display: grid; gap: 14px; padding: 22px 0 14px; background: linear-gradient(#000 88%, transparent); }
.doc-title-row { display: flex; justify-content: space-between; align-items: flex-end; gap: 16px; flex-wrap: wrap; }
.doc-title { display: grid; gap: 4px; }
.doc-title h1 { margin: 0; font-size: 28px; font-weight: 300; font-variation-settings: "wdth" 118; letter-spacing: -0.02em; color: var(--ink); }
.doc-sep { color: var(--ink-3); }
.doc-export, .doc-controls { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.doc-btn {
  display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 12px 0 10px; border-radius: 99px; border: 1px solid var(--hair);
  background: rgba(0, 0, 0, 0.6); font-size: var(--t-label); color: var(--ink-2); text-decoration: none; transition: color var(--fast), border-color var(--fast);
}
.doc-btn:hover, .doc-btn[aria-expanded="true"] { color: var(--ink); border-color: var(--hair-2); }

.doc-readout { margin: 0; display: flex; flex-wrap: wrap; align-items: flex-end; gap: 10px 24px; }
.doc-readout > div { display: grid; gap: 4px; }
.doc-readout dt { display: inline-flex; align-items: flex-end; gap: 6px; font-size: var(--t-micro); color: var(--ink-3); }
.doc-readout dd { margin: 0; color: var(--ink); }
.doc-readout dd.num { font-size: 34px; line-height: 1; }
.doc-readout dd.num.sm { font-size: 22px; }
.doc-readout .of { color: var(--ink-3); font-size: 14px; }
.doc-readout-rule { width: 1px; align-self: stretch; background: var(--hair-2); }
.doc-readout .doc-meta dd { font-size: var(--t-micro); color: var(--ink-3); }
.doc-readout.compact dd.num.sm { font-size: 20px; }

.doc-filter { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }
.doc-search { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 10px; border-radius: 99px; border: 1px solid var(--hair); color: var(--ink-3); }
.doc-search input { background: none; border: 0; outline: none; color: var(--ink); font: inherit; font-size: var(--t-label); width: 140px; }
.doc-search:focus-within { border-color: var(--sweep-hi); }
.doc-filter .dchip[data-on] { border-color: var(--sweep-hi); color: var(--ink); }
.doc-filter .dchip .num { color: var(--ink-3); font-size: var(--t-micro); }

/* ------------------------------------------------------------------------------------------- list */
.doc-band { margin-top: 18px; }
.doc-band h2 { display: flex; align-items: flex-end; gap: 8px; margin: 0 0 6px; font-size: var(--t-label); font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink); }
.doc-band h2 .num { font-size: 14px; color: var(--ink-3); letter-spacing: 0; }
.doc-list { list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--hair); }
.doc-row { border-bottom: 1px solid var(--hair); }
.doc-row > button {
  width: 100%; display: grid; grid-template-columns: 96px 12px minmax(0, 1fr) minmax(0, 240px) auto 28px 40px 52px; align-items: center; gap: 10px;
  padding: 9px 6px; text-align: left; color: var(--ink-2); border-radius: 6px; transition: background var(--fast), color var(--fast);
}
.doc-row > button:hover { background: rgba(255, 255, 255, 0.04); color: var(--ink); }
.doc-row[data-open] > button { color: var(--ink); background: rgba(255, 255, 255, 0.05); }
.doc-id { font-size: var(--t-micro); color: var(--ink-3); letter-spacing: 0.02em; font-feature-settings: "tnum" 1; }
.doc-rtitle { font-size: var(--t-body); color: var(--ink); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.doc-target { font-size: var(--t-label); color: var(--ink-2); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-variation-settings: "wdth" 112; }
.doc-basis { color: var(--ink-3); }
.doc-tags { display: inline-flex; gap: 6px; align-items: center; }
.doc-gtag { display: inline-flex; align-items: center; height: 18px; padding: 0 6px; border-radius: 4px; border: 1px solid var(--hair-2); font-size: var(--t-micro); color: var(--ink-2); white-space: nowrap; margin-left: 4px; }
.doc-gtag.dashed, .doc-gtag[data-dashed] { border-style: dashed; }
.doc-ev { font-size: var(--t-micro); color: var(--ink-3); text-align: center; }
