@keyframes prescore { from { opacity: 0.25; } to { opacity: 1; } }
@media (prefers-reduced-motion: reduce) { .prescore::before { animation: none; } }

/* challenged PM decisions (challenged.tsx): a compact line under the HUD stats; white = attention, one pulse on arrival */
.pchal { display: grid; gap: 4px; max-width: 420px; }
.pchal-head { display: inline-flex; align-items: baseline; gap: 6px; justify-self: start; font-size: var(--t-label); color: var(--ink); text-align: left; }
.pchal-head .num { font-size: 15px; }
.pchal-head:hover span:last-child { text-decoration: underline; text-underline-offset: 3px; text-decoration-color: var(--hair-2); }
.pchal-dot { position: relative; align-self: center; width: 7px; height: 7px; border-radius: 50%; background: var(--ink); flex: none; }
.pchal-dot::after { content: ""; position: absolute; inset: -4px; border-radius: 50%; box-shadow: 0 0 0 1.5px var(--ink); opacity: 0; animation: psky-pulse 1.6s var(--ease) 0.6s 1 both; }
@media (prefers-reduced-motion: reduce) { .pchal-dot::after { animation: none; } }
.pchal-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 1px; pointer-events: auto; }
.pchal-list button {
  width: calc(100% + 16px); margin-left: -8px; padding: 3px 8px; border-radius: 6px; text-align: left; display: flex; flex-wrap: wrap;
  align-items: baseline; gap: 2px 8px; background: rgba(0, 0, 0, 0.6); transition: background var(--fast);
}
.pchal-list button:hover { background: rgba(255, 255, 255, 0.07); }
.pchal-title { font-size: 13px; color: var(--ink); max-width: 230px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pchal-move { display: inline-flex; align-items: flex-end; gap: 5px; font-size: var(--t-label); color: var(--ink-2); }

/* inspector: what the PM decides on (deciding.tsx), bundle members as rows, the decision's scope line */
32:.hud-tl.phud { gap: 12px; width: max-content; max-width: calc(100vw - 2 * var(--edge) - 460px); }
209:  .phud { max-width: calc(100vw - 32px); }
61:.psky-blocked, .plist-tags .psky-blocked { display: inline-block; width: 9px; height: 9px; border-radius: 50%; box-shadow: inset 0 0 0 1.2px var(--ink); position: relative; align-self: center; }
83:.plist-tags { display: inline-flex; align-items: center; gap: 5px; }
85:.ptag, .ptag-pm {
89:.ptag[data-dashed] { box-shadow: none; outline: 1px dashed var(--ink-3); outline-offset: -1px; color: var(--ink); }
90:.ptag-pm { color: var(--sweep-hi); box-shadow: inset 0 0 0 1px rgba(77, 148, 255, 0.6); }
194:.pmatrix-cell { display: inline-flex; align-items: flex-end; justify-content: center; gap: 6px; height: 26px; padding-bottom: 6px; border-radius: 5px; transition: background var(--fast); position: relative; }
195:button.pmatrix-cell:hover { background: rgba(255, 255, 255, 0.07); }
