// "Your decisions are challenged": a compact, non-modal line in the top-left HUD when the selected checkpoint has OPEN
// proposals against PM-confirmed bands (factor_delta.against = "pm"). Proposals against the AI's own earlier band stay
// passive marks. On arrival at a checkpoint the list is open and the line pulses once (white = attention; none under
// reduced motion); folded it stays a small count until every challenged decision is accepted or rejected. A row opens
// that target's inspector, where the proposal's Accept / Reject box sits.
import { useEffect, useMemo, useState } from "react";
import type { Proposal } from "@/lib/prioritize";
import type { LineName } from "@/lib/definition";
import { useCheckpoint } from "@/state/checkpoint";
import { setView } from "../definition/store";
import { BandMark } from "./marks";
import { CAUSE_LABEL, CP_LABEL, openProposals, type PrioData } from "./data";
import { selectTarget, setP, useP } from "./store";

export function Challenged({ pd }: { pd: PrioData }) {
  const { cp } = useCheckpoint();
  useP((s) => s.pendingProposals);   // an optimistic verdict removes its row at once
  const list = pd.sample ? [] : openProposals(pd.data).filter((p) => p.against === "pm");
  const title = useMemo(() => new Map(pd.data.targets.map((t) => [t.key, t.title])), [pd.data.targets]);
  const [open, setOpen] = useState(true);
  useEffect(() => { setOpen(true); }, [cp]);   // arriving at a checkpoint opens the list again
  if (!list.length) return null;
  const at = CP_LABEL[cp] ?? cp;
  const go = (p: Proposal) => {
    setView({ line: p.line as LineName });
    setP((s) => ({ market: { ...s.market, [p.line]: p.market }, view: "skyline" }));
    selectTarget(p.key);
  };
  return (
    <section className="pchal" key={cp} aria-label="Challenged decisions" aria-live="polite">
      <button className="pchal-head" aria-expanded={open} onClick={() => setOpen((o) => !o)}>
        <i className="pchal-dot" aria-hidden />
        <span className="num">{list.length}</span>
        <span>{list.length === 1 ? "of your decisions is" : "of your decisions are"} challenged at {at}</span>
      </button>
      {open && (
        <ul className="pchal-list">
          {list.map((p) => (
            <li key={p.id}>
              <button onClick={() => go(p)} title="Open: accept or reject">
                <span className="pchal-title">{title.get(p.key) ?? p.key}</span>
                <span className="label">{p.line} · {p.market}</span>
                <span className="pchal-move">
                  <BandMark band={p.old_band} color="var(--ink-2)" size="sm" pm />{p.old_band ?? "–"}
                  <span aria-hidden>→</span>
                  <BandMark band={p.proposed_band} color="var(--ink)" size="sm" />{p.proposed_band}
                </span>
                <span className="label">{CAUSE_LABEL[p.cause] ?? p.cause}</span>
              </button>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

input.content:
// Rise / Fall in the inspector (PM request 2026-10-11): when the open target is a challenged PM decision, a coloured
// banner at the top — red when the AI now places it below the PM's band, green when above — in plain words, with the
// proposal's Accept / Reject (required rationale) right there. It replaces the lower proposal box for that target.
import { useState } from "react";
import { useCheckpoint } from "@/state/checkpoint";
import { BandMark } from "./marks";
import { CP_LABEL, factorLabel, useProposalVerdict, type PrioData } from "./data";
import { rfSentence, type RiseFall } from "./pm";

export function RiseFallBanner({ pd, rf }: { pd: PrioData; rf: RiseFall }) {
  const { cp } = useCheckpoint();
  const verdict = useProposalVerdict(pd);
  const [open, setOpen] = useState<"accept" | "reject" | null>(null);
  const [why, setWhy] = useState("");
  const p = rf.proposal;
  const down = rf.dir === "down";
  const deltas = Object.entries(p.factor_delta ?? {}).filter(([, v]) => v);
  return (
    <section className="prf-banner" data-rf={rf.dir} role="alert" aria-label={down ? "Your decision is contradicted" : "Upgrade opportunity"}>
      <p className="prf-kicker"><b aria-hidden>{down ? "▼" : "▲"}</b>{down ? "Downgrade — your decision is contradicted" : "Upgrade opportunity"}</p>
      <p className="prf-move">
        <BandMark band={rf.from} color="var(--sweep-hi)" size="md" pm /><span className="prf-pm">Your {rf.from}</span>
        <span className="prf-arrow" aria-hidden>→</span>
        <BandMark band={rf.to} color={down ? "var(--fall-hi)" : "var(--rise-hi)"} size="md" /><b>AI: {rf.to}</b>
      </p>
      <p className="prf-text">{rfSentence(rf, CP_LABEL[cp] ?? cp)}</p>
      {deltas.length > 0 && (
        <p className="prf-deltas label">{deltas.map(([k, v]) => `${factorLabel(k)} ${v > 0 ? "+" : "−"}${Math.abs(v)} pts`).join(" · ")}</p>
      )}
      {open ? (
        <form className="ladder-choose" onSubmit={(e) => { e.preventDefault(); if (why.trim().length >= 5) { verdict.mutate({ p, verdict: open, rationale: why.trim() }); setOpen(null); setWhy(""); } }}>
          <textarea rows={2} value={why} onChange={(e) => setWhy(e.target.value)} autoFocus aria-label="Rationale"
                    placeholder={open === "accept" ? `Why change to ${rf.to}? (required)` : `Why keep ${rf.from}? (required)`} />
          <div className="ladder-actions">
            <button type="submit" className="dbtn primary" disabled={why.trim().length < 5 || verdict.isPending}>{open === "accept" ? `Accept → ${rf.to}` : `Keep ${rf.from}`}</button>
            <button type="button" className="dbtn" onClick={() => setOpen(null)}>Cancel</button>
          </div>
        </form>
      ) : (
        <div className="prf-actions">
          <button className="prf-btn" data-kind="accept" onClick={() => setOpen("accept")}>Accept {rf.to}</button>
          <button className="prf-btn" onClick={() => setOpen("reject")}>Reject · keep {rf.from}</button>
        </div>
      )}
      {verdict.isError && <p className="derror">Not saved: {(verdict.error as Error).message}</p>}
      {pd.sample && <p className="label">Sample data: the verdict is kept in this view only.</p>}
    </section>
  );
}

