screens/definition/definition.css:180:.ladder-choose { display: grid; gap: 8px; padding: 2px 0 2px 12px; border-left: 1px solid var(--hair-2); }
screens/definition/definition.css:181:.ladder-choose textarea {
screens/definition/definition.css:185:.ladder-choose textarea:focus { outline: none; border-color: var(--sweep-hi); }
screens/definition/definition.css:210:.dbtn { height: 28px; padding: 0 12px; border-radius: 99px; border: 1px solid var(--hair); background: rgba(0, 0, 0, 0.6); font-size: var(--t-label); color: var(--ink-2); transition: color var(--fast), border-color var(--fast), background var(--fast); }
screens/definition/definition.css:211:.dbtn:hover:not(:disabled) { color: var(--ink); border-color: var(--hair-2); }
screens/definition/definition.css:212:.dbtn.primary { color: var(--ink); border-color: var(--hair-2); background: rgba(255, 255, 255, 0.07); }
screens/definition/definition.css:213:.dbtn:disabled { opacity: 0.4; cursor: default; }
10:.pband { display: inline-block; flex: none; position: relative; width: 8px; height: 14px; --c: var(--ink-2); }
11:.pband[data-band="Must"] { background: var(--c); border-radius: 1px; }
12:.pband[data-band="Should"] { box-shadow: inset 0 0 0 1.4px var(--c); border-radius: 1px; background: color-mix(in srgb, var(--c) 14%, transparent); height: 11px; margin-top: 3px; }
13:.pband[data-band="Could"] { width: 8px; background: linear-gradient(var(--c), var(--c)) center 3px / 1.6px calc(100% - 3px) no-repeat; height: 8px; margin-top: 6px; }
14:.pband[data-band="Could"]::before { content: ""; position: absolute; left: 2px; top: 0; width: 4px; height: 4px; border-radius: 50%; background: var(--c); }
.plist-band { color: var(--ink); gap: 8px; }
.plist-row { grid-template-columns: 18px 10px 1fr auto auto; }
.plist-rank { font-size: var(--t-micro); color: var(--ink-3); font-variant-numeric: tabular-nums; text-align: right; }
.plist-tags { display: inline-flex; align-items: center; gap: 5px; }
.plist-conf { font-size: 10px; color: var(--ink-3); letter-spacing: 0.04em; }
.ptag, .ptag-pm {
  font-size: 9.5px; font-weight: 600; letter-spacing: 0.06em; line-height: 14px; padding: 0 4px; border-radius: 3px; color: var(--ink-2);
  box-shadow: inset 0 0 0 1px var(--hair-2); white-space: nowrap;
}
.ptag[data-dashed] { box-shadow: none; outline: 1px dashed var(--ink-3); outline-offset: -1px; color: var(--ink); }
.ptag-pm { color: var(--sweep-hi); box-shadow: inset 0 0 0 1px rgba(77, 148, 255, 0.6); }

/* ------------------------------------------------------------------------------------------- inspector */
.psheet { gap: 20px; }
.psheet .sheet-layer .pband { margin-right: 2px; }
.pfigure { display: flex; align-items: center; gap: 16px; }

