/* Rise / Fall (PM request 2026-10-11; DESIGN.md → Rise/Fall rule). Red = the AI now places a PM-confirmed target BELOW
   the PM's band (a downgrade: loud, never hidden); green = ABOVE it (an upgrade opportunity: clear, calmer). Small
   coloured ▲ / ▼ = an unconfirmed AI band that moved since the previous checkpoint. These colours mark nothing else.
   Blue stays the PM's own position; amber stays loss. Shared by page 4 (skyline, HUD, inspector, matrix, list) and
   page 5 (rows, changes). */

/* ------------------------------------------------------------------------------------------- skyline labels */
.psky-cap[data-rf] { flex-wrap: wrap; justify-content: center; row-gap: 3px; max-width: 260px; transform: translateY(calc(-100% + 9px)); }
.psky-cap[data-rf="down"] { box-shadow: inset 0 0 0 1px var(--fall); background: rgba(0, 0, 0, 0.78); }
.psky-cap[data-rf="up"] { box-shadow: inset 0 0 0 1px rgba(47, 191, 113, 0.7); }
.psky-rf {
  flex-basis: 100%; display: inline-flex; align-items: center; justify-content: center; gap: 5px; margin: 3px -1px 0; padding: 2px 7px;
  border-radius: 4px; font-size: 12px; font-weight: 700; letter-spacing: 0.01em; line-height: 16px; white-space: nowrap;
}
.psky-rf b { font-size: 13px; line-height: 1; }
.psky-rf[data-rf="down"] { background: var(--fall); color: #000; box-shadow: 0 0 0 3px var(--fall-glow), 0 0 22px var(--fall-glow); }
.psky-rf[data-rf="up"] { background: rgba(47, 191, 113, 0.14); color: var(--rise-hi); font-size: 11.5px; font-weight: 600; box-shadow: inset 0 0 0 1px var(--rise), 0 0 14px var(--rise-glow); }
.psky-rf-why { font-weight: 500; }
.psky-cap[data-collide][data-rf="down"] { visibility: visible !important; }
/* the unconfirmed band moved since the previous checkpoint: the existing small arrow, coloured */
.psky-prop[data-rf="up"], .parrow[data-rf="up"] { color: var(--rise-hi); }
.psky-prop[data-rf="down"], .parrow[data-rf="down"] { color: var(--fall-hi); }
.psky-prop[data-rf] { font-size: 9px; }

/* arrival pulse: down = a strong red double ring, three beats; up = one gentle green ring */
.psky-pulse[data-rf="down"] { box-shadow: 0 0 0 2.5px var(--fall), 0 0 16px var(--fall-glow); animation: psky-pulse-fall 1.3s var(--ease) 1.2s 3 both; }
.psky-pulse-2[data-rf="down"] { animation-delay: 1.65s; }
.psky-pulse[data-rf="up"] { box-shadow: 0 0 0 1.5px var(--rise); animation: psky-pulse 1.8s var(--ease) 1.2s 1 both; }
@keyframes psky-pulse-fall { 0% { opacity: 1; transform: scale(1); } 100% { opacity: 0; transform: scale(4.6); } }
@media (prefers-reduced-motion: reduce) { .psky-pulse[data-rf], .psky-pulse-2 { display: none; animation: none; } }

/* ------------------------------------------------------------------------------------------- HUD: challenged decisions */
.pchal[data-rf] { gap: 8px; max-width: 460px; }
.pchal-head .pchal-fold { display: inline-flex; gap: 8px; margin-left: 4px; font-size: 13px; }
.pchal-dot[data-rf="down"] { background: var(--fall); box-shadow: 0 0 0 3px var(--fall-glow); }
.pchal-dot[data-rf="down"]::after { box-shadow: 0 0 0 2px var(--fall); }
.pchal-dot[data-rf="up"] { background: var(--rise); }
.pchal-dot[data-rf="up"]::after { box-shadow: 0 0 0 1.5px var(--rise); }
[data-rf="down"] > b, b[data-rf="down"] { color: var(--fall-hi); }
[data-rf="up"] > b, b[data-rf="up"] { color: var(--rise-hi); }
.pchal-group { display: grid; gap: 3px; padding-left: 10px; border-left: 3px solid; }
.pchal-group[data-rf="down"] { border-color: var(--fall); }
.pchal-group[data-rf="up"] { border-color: var(--rise); }
.pchal-ghead { margin: 0; font-size: 15px; font-weight: 600; letter-spacing: 0.01em; pointer-events: none; }
.pchal-ghead b { font-size: 17px; font-variant-numeric: tabular-nums; margin-right: 2px; }
.pchal-group[data-rf="down"] .pchal-ghead { color: var(--fall-hi); }
.pchal-group[data-rf="up"] .pchal-ghead { color: var(--rise-hi); }
.pchal-group .pchal-list button[data-rf="down"] { background: rgba(255, 59, 48, 0.12); }
.pchal-group .pchal-list button[data-rf="down"]:hover { background: rgba(255, 59, 48, 0.22); }
.pchal-group .pchal-list button[data-rf="up"] { background: rgba(47, 191, 113, 0.09); }
.pchal-group .pchal-list button[data-rf="up"]:hover { background: rgba(47, 191, 113, 0.18); }
.pchal-group .pchal-move b { color: var(--ink); font-weight: 600; }
.pchal-group[data-rf="down"] .pchal-arrow { color: var(--fall-hi); }
.pchal-group[data-rf="up"] .pchal-arrow { color: var(--rise-hi); }

/* ------------------------------------------------------------------------------------------- inspector banner */
.prf-banner { display: grid; gap: 8px; padding: 12px 14px; border-radius: 8px; border-left: 4px solid; }
.prf-banner[data-rf="down"] { background: rgba(255, 59, 48, 0.13); border-color: var(--fall); box-shadow: inset 0 0 0 1px rgba(255, 59, 48, 0.45), 0 0 26px var(--fall-glow); }
.prf-banner[data-rf="up"] { background: rgba(47, 191, 113, 0.09); border-color: var(--rise); box-shadow: inset 0 0 0 1px rgba(47, 191, 113, 0.35); }
.prf-kicker { margin: 0; display: flex; align-items: center; gap: 8px; font-size: 13px; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; }
.prf-kicker b { font-size: 18px; line-height: 1; }
.prf-banner[data-rf="down"] .prf-kicker { color: var(--fall-hi); }
.prf-banner[data-rf="up"] .prf-kicker { color: var(--rise-hi); }
.prf-move { margin: 0; display: flex; align-items: flex-end; gap: 8px; font-size: 20px; font-weight: 300; font-stretch: 112%; color: var(--ink); }
.prf-move b { font-weight: 600; }
.prf-pm { color: var(--sweep-hi); }
.prf-arrow { color: var(--ink-2); }
.prf-text { margin: 0; font-size: var(--t-body); line-height: 1.45; color: var(--ink); }
.prf-deltas { margin: 0; color: var(--ink-2); }
.prf-actions { display: flex; gap: 8px; flex-wrap: wrap; }
.prf-btn {
  height: 30px; padding: 0 14px; border-radius: 99px; border: 1px solid var(--hair-2); background: rgba(0, 0, 0, 0.5); font-size: var(--t-label);
  font-weight: 600; color: var(--ink); transition: background var(--fast), border-color var(--fast);
}
.prf-btn:hover { background: rgba(255, 255, 255, 0.08); }
.prf-banner[data-rf="down"] .prf-btn[data-kind="accept"] { background: var(--fall); border-color: var(--fall); color: #000; }
.prf-banner[data-rf="up"] .prf-btn[data-kind="accept"] { background: var(--rise); border-color: var(--rise); color: #000; }
.prf-banner .prf-btn[data-kind="accept"]:hover { filter: brightness(1.1); }

/* ------------------------------------------------------------------------------------------- list, matrix */
.prf-tag { font-size: 10.5px; font-weight: 700; line-height: 16px; padding: 0 5px; border-radius: 3px; white-space: nowrap; }
.prf-tag[data-rf="down"] { background: var(--fall); color: #000; box-shadow: 0 0 10px var(--fall-glow); }
.prf-tag[data-rf="up"] { color: var(--rise-hi); box-shadow: inset 0 0 0 1px var(--rise); background: rgba(47, 191, 113, 0.12); }
.plist-row[data-rf], .doc-row[data-rf] > button { position: relative; }
.plist-row[data-rf]::before, .doc-row[data-rf] > button::before { content: ""; position: absolute; left: 0; top: 4px; bottom: 4px; width: 3px; border-radius: 2px; }
.plist-row[data-rf="down"]::before, .doc-row[data-rf="down"] > button::before { background: var(--fall); }
.plist-row[data-rf="up"]::before, .doc-row[data-rf="up"] > button::before { background: var(--rise); }
.plist-row[data-rf="down"], .doc-row[data-rf="down"] > button { background: rgba(255, 59, 48, 0.08); }
.prf-cell { position: absolute; right: 2px; top: 1px; font-size: 10px; font-weight: 800; line-height: 1; letter-spacing: 0.02em; }
.prf-cell[data-rf="down"] { color: var(--fall-hi); text-shadow: 0 0 8px var(--fall-glow); }
.prf-cell[data-rf="up"] { color: var(--rise-hi); }
.pmatrix-cell[data-rf="down"] { box-shadow: inset 0 0 0 1.5px var(--fall); background: rgba(255, 59, 48, 0.12); }
.pmatrix-cell[data-rf="up"] { box-shadow: inset 0 0 0 1px var(--rise); background: rgba(47, 191, 113, 0.08); }
.prf-legend { display: inline-flex; align-items: baseline; gap: 4px; }
.prf-legend[data-rf="down"] b { color: var(--fall-hi); }
.prf-legend[data-rf="up"] b { color: var(--rise-hi); }

/* ------------------------------------------------------------------------------------------- page 5 */
.doc-rf { display: inline-flex; align-items: center; height: 18px; padding: 0 6px; border-radius: 4px; font-size: var(--t-micro); font-weight: 700; white-space: nowrap; margin-left: 4px; }
.doc-rf[data-rf="down"] { background: var(--fall); color: #000; box-shadow: 0 0 10px var(--fall-glow); }
.doc-rf[data-rf="up"] { color: var(--rise-hi); box-shadow: inset 0 0 0 1px var(--rise); background: rgba(47, 191, 113, 0.12); }
.doc-delta[data-rf="up"] { color: var(--rise-hi) !important; }
.doc-delta[data-rf="down"] { color: var(--fall-hi) !important; }
.doc-rail[data-rf="down"] { border-left-color: var(--fall) !important; color: var(--ink); }
.doc-rail[data-rf="up"] { border-left-color: var(--rise) !important; color: var(--ink); }
.doc-rfgroup { display: grid; gap: 4px; padding: 8px 0 8px 12px; border-left: 3px solid; margin-bottom: 12px; }
.doc-rfgroup[data-rf="down"] { border-color: var(--fall); background: linear-gradient(to right, rgba(255, 59, 48, 0.1), transparent 70%); }
.doc-rfgroup[data-rf="up"] { border-color: var(--rise); background: linear-gradient(to right, rgba(47, 191, 113, 0.07), transparent 70%); }
.doc-rfgroup h3 { margin: 0 0 2px; font-size: 14px; font-weight: 700; letter-spacing: 0.01em; }
.doc-rfgroup[data-rf="down"] h3 { color: var(--fall-hi); }
.doc-rfgroup[data-rf="up"] h3 { color: var(--rise-hi); }
.doc-rfgroup ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 3px; }
.doc-rfgroup li { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 10px; font-size: var(--t-body); color: var(--ink); }
.doc-rfgroup li button { color: var(--ink); text-align: left; }
.doc-rfgroup li button:hover { text-decoration: underline; text-underline-offset: 3px; }

/* guide marks */
.gmark-rf { display: inline-grid; place-items: center; width: 18px; height: 18px; font-size: 12px; font-weight: 800; border-radius: 3px; flex: none; }
.gmark-rf[data-rf="down"] { background: var(--fall); color: #000; }
.gmark-rf[data-rf="up"] { color: var(--rise-hi); box-shadow: inset 0 0 0 1px var(--rise); }
.gmark-rf[data-small] { background: none; box-shadow: none; font-size: 9px; }
.gmark-rf[data-small][data-rf="down"] { color: var(--fall-hi); }

